"<script>\n"
"const $ = id => document.getElementById(id);\n"
"const fmt = (v, d = 1) => Number(v).toLocaleString('pt-BR', { minimumFractionDigits: d, maximumFractionDigits: d });\n"
"let last = null, editing = false, shown = null, optsEditing = false;\n"
"const RANGE = 30;\n"
"const pos = deg => 50 + Math.max(-RANGE, Math.min(RANGE, deg)) / RANGE * 50;\n"
"\n"
"function render(s) {\n"
"  last = s;\n"
"  const live = s.connected && s.age_ms < 1500;\n"
"  $('status').textContent = live ? (s.centred ? 'PS Move conectado' : 'PS Move conectado · deixe o tubo parado no meio') : 'PS Move desconectado · ligue o Move (botão PS)';\n"
"  $('status').className = 'status ' + (live ? 'ok' : 'bad');\n"
"  /* Sensor noise is about ±0.5°: hold the needle until the change is real. */\n"
"  if (shown === null || Math.abs(s.tilt - shown) >= 0.8) shown = s.tilt;\n"
"  if (Math.abs(shown) < 2) shown = 0;\n"
"  $('needle').style.left = pos(shown) + '%';\n"
"  $('zoneUp').style.left = pos(s.level + s.on) + '%'; $('zoneUp').style.right = '0';\n"
"  $('levelMark').style.left = pos(s.level) + '%';\n"
"  $('zoneDown').style.left = '0'; $('zoneDown').style.width = pos(s.level - s.on) + '%';\n"
"  $('tilt').textContent = (shown > 0 ? '+' : '') + fmt(shown) + '°';\n"
"  const st = $('state');\n"
"  st.textContent = s.state === 1 ? 'indo para frente' : s.state === 2 ? 'indo para trás' : 'parado no nível ' + (s.level > 0 ? '+' : '') + fmt(s.level) + '°';\n"
"  st.className = 'pill' + (s.state === 1 ? ' up' : s.state === 2 ? ' down' : '');\n"
"  $('extra').textContent = 'lado ' + fmt(s.side) + '° · giro ' + fmt(s.gyro, 0) + '°/s' + (s.forward_taught ? ' · frente ensinada' : '');\n"
"  $('ups').textContent = s.ups; $('downs').textContent = s.downs;\n"
"  $('rests').innerHTML = s.rests.slice().sort((a, b) => b.deg - a.deg)\n"
"    .map(r => `<tr><td>${(r.deg > 0 ? '+' : '') + fmt(r.deg)}°</td><td>${r.hits}</td></tr>`).join('') || '<tr><td colspan=\"2\" class=\"status\">Nenhuma ainda</td></tr>';\n"
"  $('events').innerHTML = s.events.slice(0, 12)\n"
"    .map(e => `<tr><td>${e.kind === 'up' ? '▲ subiu' : '▼ desceu'}</td><td>${fmt(e.peak)}°</td><td>${fmt(e.gyro, 0)}°/s</td><td>${e.ms} ms</td><td>${fmt(e.ago_ms / 1000)} s</td></tr>`).join('') || '<tr><td colspan=\"5\" class=\"status\">Nenhuma ainda</td></tr>';\n"
"  const names = [['move', 'Move'], ['t', 'T'], ['cross', '✕'], ['circle', '○'], ['square', '□'], ['triangle', '△']];\n"
"  $('btns').innerHTML = names.map(([k, n]) => `<span class=\"${s[k] ? 'on' : ''}\">${n}</span>`).join('');\n"
"  $('trig').textContent = s.trigger; $('trigBar').style.width = (s.trigger / 255 * 100) + '%';\n"
"  if (!editing) { $('on').value = s.on; $('off').value = s.off; }\n"
"  if (!optsEditing) {\n"
"    $('use').value = !s.enabled ? 'off' : s.lever ? 'lever' : 'shift';\n"
"    $('fast').checked = !!s.fast;\n"
"    $('leverDeg').value = s.lever_deg;\n"
"    $('leverHold').value = String(s.lever_hold);\n"
"    ['up', 'down', 'handbrake'].forEach(k => $(k).value = String(s[k]));\n"
"    showUse();\n"
"  }\n"
"  const mode = !s.fast ? 'modo nível' : s.learned ? 'modo rápido ativo' : `modo rápido aprendendo: mude de nível ${3 - s.learn_count} vez(es) devagar`;\n"
"  $('optsInfo').textContent = !s.enabled ? 'Desligado · só medindo, nada chega ao jogo.'\n"
"    : s.lever ? (s.lever_pulled ? 'Freio de mão PUXADO' : 'Freio de mão solto') + (s.handbrake ? '' : ' · escolha o botão do freio')\n"
"    : `Câmbio · ${s.sent} trocas enviadas ao jogo · ${mode}.`;\n"
"}\n"
"\n"
"async function poll() {\n"
"  try {\n"
"    const r = await fetch('/api/shifter', { cache: 'no-store' });\n"
"    if (r.ok) render(await r.json());\n"
"  } catch (e) { $('status').textContent = 'Sem resposta do PS5'; $('status').className = 'status bad'; }\n"
"  setTimeout(poll, 100);\n"
"}\n"
"\n"
"async function post(path, data) {\n"
"  const r = await fetch(path, { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams(data) });\n"
"  $('msg').textContent = r.ok ? 'Feito.' : 'Valor recusado.';\n"
"  return r.ok;\n"
"}\n"
"\n"
"['on', 'off'].forEach(id => { $(id).addEventListener('focus', () => editing = true); $(id).addEventListener('blur', () => editing = false); });\n"
"$('saveTh').onclick = async () => { await post('/api/shifter/thresholds', { on: $('on').value, off: $('off').value }); editing = false; };\n"
"$('centre').onclick = () => post('/api/shifter/centre', { centre: '1' });\n"
"const PAD_BUTTONS = [[16384, 'Cruz (X)'], [8192, 'Círculo'], [32768, 'Quadrado'], [4096, 'Triângulo'], [1024, 'L1'], [2048, 'R1'],\n"
"  [256, 'L2'], [512, 'R2'], [2, 'L3'], [4, 'R3'], [16, 'Cima'], [64, 'Baixo'], [128, 'Esquerda'], [32, 'Direita'], [8, 'Options'], [1048576, 'Touchpad']];\n"
"['up', 'down', 'handbrake'].forEach(id => {\n"
"  const sel = $(id);\n"
"  sel.innerHTML = `<option value=\"0\">${sel.dataset.none}</option>` + PAD_BUTTONS.map(([v, n]) => `<option value=\"${v}\">${n}</option>`).join('');\n"
"});\n"
"function showUse() {\n"
"  const use = $('use').value;\n"
"  document.querySelectorAll('.for-shift').forEach(el => el.hidden = use !== 'shift');\n"
"  document.querySelectorAll('.for-lever').forEach(el => el.hidden = use !== 'lever');\n"
"  $('hbLabel').textContent = use === 'lever' ? 'Botão do freio de mão' : 'Freio de mão (gatilho T)';\n"
"  $('optsHelp').textContent = use === 'lever'\n"
"    ? 'Na posição normal o freio fica solto. Puxe o tubo para trás para segurar o botão; volte para a frente para soltar.'\n"
"      + ($('leverHold').value !== '0' ? ' Só aciona com o botão escolhido apertado junto.' : '')\n"
"    : use === 'shift' ? 'Escolha os mesmos botões que o jogo usa para trocar de marcha.' : '';\n"
"}\n"
"['use', 'fast', 'up', 'down', 'handbrake', 'leverDeg', 'leverHold'].forEach(id => $(id).addEventListener('change', () => { optsEditing = true; showUse(); }));\n"
"$('testUp').onclick = () => post('/api/shifter/test', { kind: 'up' });\n"
"$('testDown').onclick = () => post('/api/shifter/test', { kind: 'down' });\n"
"$('saveOpts').onclick = async () => {\n"
"  const use = $('use').value;\n"
"  await post('/api/shifter/options', {\n"
"    enabled: use === 'off' ? '0' : '1', lever: use === 'lever' ? '1' : '0', lever_deg: $('leverDeg').value, lever_hold: $('leverHold').value,\n"
"    fast: $('fast').checked ? '1' : '0', handbrake: $('handbrake').value, up: $('up').value, down: $('down').value\n"
"  });\n"
"  optsEditing = false;\n"
"};\n"
"$('reset').onclick = () => post('/api/shifter/reset', { reset: '1' });\n"
"$('export').onclick = () => {\n"
"  if (!last) return;\n"
"  const d = new Date(), p = n => String(n).padStart(2, '0');\n"
"  const name = `cambio-move-${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}-${p(d.getHours())}${p(d.getMinutes())}.json`;\n"
"  const a = document.createElement('a');\n"
"  const shifter = { ...last, events: last.events.map(e => ({ ...e, at: new Date(d - e.ago_ms).toLocaleTimeString('pt-BR', { hour12: false }) + '.' + String((d - e.ago_ms) % 1000).padStart(3, '0') })) };\n"
"  a.href = URL.createObjectURL(new Blob([JSON.stringify({ exported: d.toISOString(), shifter }, null, 2)], { type: 'application/json' }));\n"
"  a.download = name; a.click(); URL.revokeObjectURL(a.href);\n"
"};\n"
"poll();\n"
"</script>\n"
"</body>\n"
"</html>\n";
